package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

var WsEofFlag string          // PIC X len=1 = "N"
var WsInterest decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal   // PIC 9(11)V99 len=13 = 0
var WsCount int64             // PIC 9(5) len=5 = 0
var WsPrinEd string           // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string            // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string          // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var LoanRecVar LoanRec

var loanFile *os.File
var loanScanner *bufio.Scanner
var atEnd bool

func parsePic9V99(raw string, scale int32) decimal.Decimal {
	// raw length = width, may contain spaces
	// build digit string: digit -> keep, otherwise '0'
	b := make([]byte, 0, len(raw))
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			b = append(b, byte(ch))
		} else if ch == ' ' {
			b = append(b, '0')
		} else {
			// treat any other as 0
			b = append(b, '0')
		}
	}
	if len(b) == 0 {
		return decimal.Zero
	}
	s := string(b)
	// parse as integer
	d, err := decimal.NewFromString(s)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-scale)
}

func parsePic9Int(raw string) int64 {
	b := make([]byte, 0, len(raw))
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			b = append(b, byte(ch))
		} else if ch == ' ' {
			b = append(b, '0')
		} else {
			b = append(b, '0')
		}
	}
	if len(b) == 0 {
		return 0
	}
	s := string(b)
	// trim leading zeros but keep at least one
	var v int64
	for _, c := range s {
		v = v*10 + int64(c-'0')
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func truncateHighOrder(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	totalDigits := int64(intDigits) + int64(scale)
	// scaled integer
	scaled := val.Shift(scale)
	// truncate fractional beyond scale (should already be scale)
	scaled = scaled.Truncate(0)
	mod := decimal.NewFromInt(1).Shift(int32(totalDigits))
	// q = trunc(scaled / mod)
	q := scaled.Div(mod).Truncate(0)
	remainder := scaled.Sub(q.Mul(mod))
	return remainder.Shift(-scale)
}

func storeInterest(val decimal.Decimal) decimal.Decimal {
	// PIC 9(9)V99
	// value already rounded to scale 2, now apply high-order truncation
	return truncateHighOrder(val, 9, 2)
}

func storeTotal(val decimal.Decimal) decimal.Decimal {
	return truncateHighOrder(val, 11, 2)
}

func storeCount(val int64) int64 {
	// PIC 9(5) keep low 5 digits
	mod := int64(100000)
	// handle negative? keep sign?
	if val < 0 {
		// for negative, take modulo on absolute and reapply sign
		// COBOL low-order truncation preserves sign? Use simple modulo
		// Use remainder approach similar to decimal
		neg := -val
		rem := neg % mod
		return -rem
	}
	return val % mod
}

func formatEdited(val decimal.Decimal, picture string) string {
	// Determine scale = count of '9'/'Z' after '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracPlaceCount := 0
	for _, ch := range fracPic {
		if ch == '9' || ch == 'Z' {
			fracPlaceCount++
		}
	}
	// integer placeholders count and list of placeholder chars in order
	intPlaceCount := 0
	intPlaceChars := []byte{} // in order of appearance
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			intPlaceCount++
			intPlaceChars = append(intPlaceChars, byte(ch))
		}
	}
	// get absolute value string handling sign separately (unsigned assumption)
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// Ensure value has exactly fracPlaceCount scale for formatting (truncate/pad)
	// We assume val already at correct scale; but get integer and fractional parts
	// Get scaled integer: val * 10^fracPlaceCount truncated
	scaled := val.Shift(int32(fracPlaceCount)).Truncate(0)
	// For negative, scaled is positive because we negated
	// Derive integer part and fractional part
	powFrac := decimal.NewFromInt(1).Shift(int32(fracPlaceCount))
	intPartDec := scaled.Div(powFrac).Truncate(0)
	fracPartDec := scaled.Sub(intPartDec.Mul(powFrac))
	// intPart as integer string without sign
	intStrRaw := intPartDec.StringFixed(0) // no decimal
	// intStrRaw may be "0"
	// Need to keep low-order digits if overflow: keep rightmost intPlaceCount digits
	if len(intStrRaw) > intPlaceCount {
		intStrRaw = intStrRaw[len(intStrRaw)-intPlaceCount:]
	}
	// pad leading zeros to intPlaceCount
	if len(intStrRaw) < intPlaceCount {
		intStrRaw = strings.Repeat("0", intPlaceCount-len(intStrRaw)) + intStrRaw
	}
	// frac part string padded
	fracStrRaw := ""
	if fracPlaceCount > 0 {
		// fracPartDec is integer < powFrac
		fracInt := fracPartDec.IntPart() // fits int64 for small scale 2
		fracStrRaw = fmt.Sprintf("%0*d", fracPlaceCount, fracInt)
		// if fracPartDec has more digits due to large value, use string
		if len(fracStrRaw) > fracPlaceCount {
			fracStrRaw = fracStrRaw[len(fracStrRaw)-fracPlaceCount:]
		}
	}

	// Now build result
	// For integer picture part, we need to map placeholders to digits
	// Find first non-zero index in intStrRaw
	firstNonZero := intPlaceCount // means all zero
	for i, c := range intStrRaw {
		if c != '0' {
			firstNonZero = i
			break
		}
	}

	result := []byte(picture) // copy picture bytes to overwrite placeholders

	// Iterate over picture indices for intPic part (0 .. dotIdx-1)
	placeIdx := 0 // index into intStrRaw / intPlaceChars
	seenNonSuppressed := false // have we displayed a digit (non-suppressed)?
	// We need to know for each placeholder whether it's suppressed
	// suppressed = placeIdx < firstNonZero && intPlaceChars[placeIdx]=='Z'
	// Then digit display suppressed flag determines seenNonSuppressed
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			digit := intStrRaw[placeIdx]
			isZ := ch == 'Z'
			suppressed := placeIdx < firstNonZero && isZ
			var out byte
			if suppressed {
				out = ' '
			} else {
				out = byte(digit)
				seenNonSuppressed = true
			}
			result[i] = out
			placeIdx++
		} else if ch == ',' {
			if !seenNonSuppressed {
				// if still in suppression zone, comma becomes space
				// suppression zone is until we have displayed a digit
				// Need to check if we are still before first displayed digit
				// We track seenNonSuppressed; if not yet seen, space
				result[i] = ' '
			} else {
				result[i] = ','
			}
		} else {
			result[i] = byte(ch)
		}
	}
	if dotIdx >= 0 {
		result[dotIdx] = '.'
		fPlaceIdx := 0
		for i := dotIdx + 1; i < len(picture); i++ {
			ch := picture[i]
			if ch == '9' || ch == 'Z' {
				result[i] = fracStrRaw[fPlaceIdx]
				fPlaceIdx++
			} else {
				result[i] = byte(ch)
			}
		}
	}
	// Negative handling: if negative, replace leading space with '-'? For unsigned pics, ignore
	if neg {
		// Put minus at last leading space before number, simple: find first non-space that is digit
		for i, c := range result {
			if c != ' ' && c != ',' && c != '.' {
				if i > 0 {
					result[i-1] = '-'
				} else {
					// no room
				}
				break
			}
		}
	}
	return string(result)
}

func formatWsCount() string {
	// PIC 9(5) zero-padded
	return fmt.Sprintf("%05d", WsCount)
}

func READ_PARA() {
	if loanScanner == nil {
		WsEofFlag = "Y"
		atEnd = true
		return
	}
	if !loanScanner.Scan() {
		WsEofFlag = "Y"
		atEnd = true
		return
	}
	line := loanScanner.Text()
	// pad with spaces to 21
	if len(line) < 21 {
		line = padRight(line, 21)
	} else if len(line) > 21 {
		line = line[:21]
	}
	// parse fields
	LoanRecVar.LrAcct = line[0:6]
	LoanRecVar.LrPrincipal = parsePic9V99(line[6:15], 2)
	LoanRecVar.LrRate = parsePic9V99(line[15:19], 2)
	LoanRecVar.LrYears = parsePic9Int(line[19:21])
}

func PROCESS_PARA() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	yearsDec := decimal.NewFromInt(LoanRecVar.LrYears)
	prod := LoanRecVar.LrPrincipal.Mul(LoanRecVar.LrRate).Mul(yearsDec)
	// divide by 100 = shift -2
	prod = prod.Shift(-2)
	// ROUND to scale 2 half away from zero
	// shopspring Round uses half away? use Round
	rounded := prod.Round(2)
	WsInterest = storeInterest(rounded)

	WsTotal = storeTotal(WsTotal.Add(WsInterest))
	WsCount = storeCount(WsCount + 1)

	WsPrinEd = formatEdited(LoanRecVar.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	// LR-ACCT is X(6) exactly 6 chars
	fmt.Printf("%s %s %s\n", LoanRecVar.LrAcct, WsPrinEd, WsIntEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("RECORDS: %s\n", formatWsCount())
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsInterest = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	WsCount = 0
	atEnd = false

	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty (COBOL would error, but we handle)
		// To mimic COBOL, error to stderr and exit non-zero
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	loanFile = f
	defer f.Close()
	loanScanner = bufio.NewScanner(f)
	// allow long lines (though 21 bytes, default 64k is fine)
	// No split customization needed (LINE SEQUENTIAL)

	// OPEN INPUT LOAN-FILE
	// PERFORM READ-PARA
	READ_PARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE LOAN-FILE
	// PERFORM SUMMARY-PARA
	SUMMARY_PARA()
}
